begin;
select plan(19);
select has_table('public', 'alert_rules', 'durable private rules exist');
select has_table('public', 'alert_events', 'history is separate from rule memory');
select public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1', 'AAPL', 'above', 100, 'USD', null);
select public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2', 'AAPL', 'above', 0, 'USD', null);
select public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3', 'AAPL', 'above', -1, 'USD', null);
select public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa4', 'AAPL', 'above', 101, 'USD', null);
select throws_ok($$select public.save_alert_rule('22222222-2222-4222-8222-222222222222', gen_random_uuid(), 'AAPL', 'below', 100, 'USD', null)$$, 'P0001', 'An asset can have up to four alerts.', 'all four can share one direction but fifth is denied');
select is((public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1', 'AAPL', 'above', 100, 'USD', null)).revision, 1, 'duplicate create id is idempotent');
select is((public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1', 'AAPL', 'above', 100, 'USD', 1)).revision, 1, 'no-op edit retains generation');
select is((public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1', 'AAPL', 'below', 100, 'USD', 1)).revision, 2, 'meaningful edit starts generation');
select throws_ok($$select public.save_alert_rule('22222222-2222-4222-8222-222222222222', 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1', 'AAPL', 'above', 99, 'USD', 1)$$, 'P0001', 'This alert changed. Reload before editing.', 'stale edit cannot overwrite newer condition');
set local role anon;
select throws_ok('select * from public.alert_rules', '42501', null, 'guest cannot read rules');
select throws_ok('select * from public.alert_events', '42501', null, 'guest cannot read history');
reset role;
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}', true);
select is((select count(*) from public.alert_rules), 0::bigint, 'another user cannot read rules');
select results_eq('delete from public.alert_rules returning id', array[]::uuid[], 'another user cannot delete rules');
select throws_ok('update public.alert_rules set armed = true', '42501', null, 'browser cannot rearm state');
select throws_ok('select public.claim_alert_work()', '42501', null, 'browser cannot invoke evaluator');
select throws_ok('select * from private.alert_installations', '42501', null, 'subscriptions are inaccessible');
select set_config('request.jwt.claims', '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}', true);
select is((select count(*) from public.alert_rules), 0::bigint, 'admin cannot read another account');
select set_config('request.jwt.claims', '{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}', true);
select is((select count(*) from public.alert_rules), 4::bigint, 'owner reads all four rules');
select throws_ok($$insert into public.alert_events (user_id) values (auth.uid())$$, '42501', null, 'owner cannot forge history');
reset role;
delete from auth.users where id = '22222222-2222-4222-8222-222222222222';
select is((select count(*) from public.alert_rules where user_id = '22222222-2222-4222-8222-222222222222'), 0::bigint, 'deletion cascades rules');
select is((select count(*) from public.assets where symbol = 'AAPL'), 1::bigint, 'deletion retains shared identity');
select * from finish();
rollback;
